input.command:
python3 -I - <<'E'
import json,glob
rows={}
for f in glob.glob('/tmp/w/data/*.json'):
    for c in json.load(open(f))['companies']:
        rows[c['id']]=c
dt=sorted([c for c in rows.values() if 'Developer Tools' in c['tags']],key=lambda c:(c['batch']!='W25',c['name'].lower()))
print("| Batch | Company | Description | HQ | Team | Hiring | Website |\n|---|---|---|---|---|---|---|")
for c in dt:
    loc=', '.join(c['locations']) if c.get('locations') else '—'
    print(f"| {c['batch']} | {c['name']} | {c['oneLiner'].replace('|','/').strip()} | {loc} | {c['teamSize'] if c['teamSize'] is not None else '—'} | {'Yes' if 'isHiring' in c['badges'] else 'No'} | {c['website']} |")
E

